VALUES ('3dda1048-2404-4b5b-94fd-04caf1f37913', 1, 'A', 2, 'Tebak halaman', 38, 'multiple_choice', 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَTerdapat pada halaman', '["Halaman 10","Halaman 9","Halaman 8","Halaman 7"]'::jsonb, 'Halaman 10', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('9018dac6-de18-4513-8dbc-024875774f5d', 1, 'A', 2, 'Tebak halaman', 39, 'multiple_choice', 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَTerdapat pada halaman', '["Halaman 10","Halaman 9","Halaman 8","Halaman 7"]'::jsonb, 'Halaman 10', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('40089541-7750-4a1e-b337-19577934e685', 1, 'A', 2, 'Tebak halaman', 40, 'multiple_choice', 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَTerdapat pada halaman', '["Halaman 10","Halaman 9","Halaman 8","Halaman 7"]'::jsonb, 'Halaman 10', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('9aa874e0-0187-4e94-850e-44e88eded887', 1, 'A', 2, 'Tebak halaman', 41, 'multiple_choice', 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَTerdapat pada halaman', '["Halaman 10","Halaman 9","Halaman 8","Halaman 7"]'::jsonb, 'Halaman 10', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('8b87e272-7277-4742-a7de-ffb5d3de90be', 1, 'A', 2, 'Tebak halaman', 42, 'multiple_choice', 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَTerdapat pada halaman', '["Halaman 10","Halaman 9","Halaman 8","Halaman 7"]'::jsonb, 'Halaman 10', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('cb398f55-edb8-46e1-820e-00bde0b1faf0', 1, 'A', 2, 'Tebak halaman', 43, 'multiple_choice', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَTerdapat pada halaman', '["Halaman 6","Halaman 5","Halaman 4","Halaman 3","Halaman 2","Halaman 1"]'::jsonb, 'Halaman 6', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('5aa8503d-d394-427a-b623-51be8807c5e0', 1, 'A', 2, 'Tebak halaman', 44, 'multiple_choice', 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَTerdapat pada halaman', '["Halaman 6","Halaman 5","Halaman 4","Halaman 3","Halaman 2","Halaman 1"]'::jsonb, 'Halaman 6', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('42d65869-ab01-427f-b1a5-9c9d3c499b2f', 1, 'A', 2, 'Tebak halaman', 45, 'multiple_choice', 'إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا ۘ يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَTerdapat pada halaman', '["Halaman 6","Halaman 5","Halaman 4","Halaman 3","Halaman 2","Halaman 1"]'::jsonb, 'Halaman 6', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('f0b56e68-50b8-4b57-8d81-0e1479cfc7bb', 1, 'A', 2, 'Tebak halaman', 46, 'multiple_choice', 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَTerdapat pada halaman', '["Halaman 6","Halaman 5","Halaman 4","Halaman 3","Halaman 2","Halaman 1"]'::jsonb, 'Halaman 6', true, 1);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, section_title, question_number, question_type, question_text, options, correct_answer, is_active, points)
VALUES ('1f17f3ba-0661-4e7c-9f87-f9710c959f0e', 1, 'A', 2, 'Tebak halaman', 47, 'multiple_choice', 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَTerdapat pada halaman', '["Halaman 6","Halaman 5","Halaman 4","Halaman 3","Halaman 2","Halaman 1"]'::jsonb, 'Halaman 6', true, 1);
